181	void BackupImpl::open(const ContextPtr & context)
182	{
183	    std::lock_guard lock{mutex};
184	
185	    if (open_mode == OpenMode::WRITE)
186	    {
187	        timestamp = std::time(nullptr);
188	        if (!uuid)
189	            uuid = UUIDHelpers::generateV4();
190	        lock_file_name = use_archives ? (archive_params.archive_name + ".lock") : ".lock";
191	        writing_finalized = false;
192	
193	        /// Check that we can write a backup there and create the lock file to own this destination.
194	        checkBackupDoesntExist();
195	        if (!is_internal_backup)
196	            createLockFile();
197	        checkLockFile(true);
198	    }
199	
200	    if (open_mode == OpenMode::READ)
201	        readBackupMetadata();
202	
203	    if (base_backup_info)
204	    {
205	        BackupFactory::CreateParams params;
206	        params.backup_info = *base_backup_info;
207	        params.open_mode = OpenMode::READ;
208	        params.context = context;
209	        base_backup = BackupFactory::instance().createBackup(params);
210	
211	        if (open_mode == OpenMode::WRITE)
212	            base_backup_uuid = base_backup->getUUID();
213	        else if (base_backup_uuid != base_backup->getUUID())
214	            throw Exception(ErrorCodes::WRONG_BASE_BACKUP, "Backup {}: The base backup {} has different UUID ({} != {})",
215	                            backup_name, base_backup->getName(), toString(base_backup->getUUID()), (base_backup_uuid ? toString(*base_backup_uuid) : ""));
216	    }
217	}
