241	void BackupImpl::writeBackupMetadata()
242	{
243	    assert(!is_internal_backup);
244	
245	    Poco::AutoPtr<Poco::Util::XMLConfiguration> config{new Poco::Util::XMLConfiguration()};
246	    config->setUInt("version", CURRENT_BACKUP_VERSION);
247	    config->setString("timestamp", toString(LocalDateTime{timestamp}));
248	    config->setString("uuid", toString(*uuid));
249	
250	    auto all_file_infos = coordination->getAllFileInfos();
251	
252	    if (base_backup_info)
253	    {
254	        bool base_backup_in_use = false;
255	        for (const auto & info : all_file_infos)
256	        {
257	            if (info.base_size)
258	                base_backup_in_use = true;
259	        }
260	
261	        if (base_backup_in_use)
262	        {
263	            config->setString("base_backup", base_backup_info->toString());
264	            config->setString("base_backup_uuid", toString(*base_backup_uuid));
265	        }
266	    }
267	
268	    size_t index = 0;
269	    for (const auto & info : all_file_infos)
270	    {
271	        String prefix = index ? "contents.file[" + std::to_string(index) + "]." : "contents.file.";
272	        config->setString(prefix + "name", info.file_name);
273	        config->setUInt(prefix + "size", info.size);
274	        if (info.size)
275	        {
276	            config->setString(prefix + "checksum", hexChecksum(info.checksum));
277	            if (info.base_size)
278	            {
279	                config->setBool(prefix + "use_base", true);
280	                if (info.base_size != info.size)
281	                {
282	                    config->setUInt(prefix + "base_size", info.base_size);
283	                    config->setString(prefix + "base_checksum", hexChecksum(info.base_checksum));
284	                }
285	            }
286	            if (!info.data_file_name.empty() && (info.data_file_name != info.file_name))
287	                config->setString(prefix + "data_file", info.data_file_name);
288	            if (!info.archive_suffix.empty())
289	                config->setString(prefix + "archive_suffix", info.archive_suffix);
290	            if (info.pos_in_archive != static_cast<size_t>(-1))
291	                config->setUInt64(prefix + "pos_in_archive", info.pos_in_archive);
292	        }
293	        ++index;
294	    }
295	
296	    std::ostringstream stream; // STYLE_CHECK_ALLOW_STD_STRING_STREAM
297	    config->save(stream);
298	    String str = stream.str();
299	
300	    checkLockFile(true);
301	
302	    std::unique_ptr<WriteBuffer> out;
303	    if (use_archives)
304	        out = getArchiveWriter("")->writeFile(".backup");
305	    else
306	        out = writer->writeFile(".backup");
307	    out->write(str.data(), str.size());
308	    out->finalize();
309	}
