311	void BackupImpl::readBackupMetadata()
312	{
313	    std::unique_ptr<ReadBuffer> in;
314	    if (use_archives)
315	    {
316	        if (!reader->fileExists(archive_params.archive_name))
317	            throw Exception(ErrorCodes::BACKUP_NOT_FOUND, "Backup {} not found", backup_name);
318	        in = getArchiveReader("")->readFile(".backup");
319	    }
320	    else
321	    {
322	        if (!reader->fileExists(".backup"))
323	            throw Exception(ErrorCodes::BACKUP_NOT_FOUND, "Backup {} not found", backup_name);
324	        in = reader->readFile(".backup");
325	    }
326	
327	    String str;
328	    readStringUntilEOF(str, *in);
329	    std::istringstream stream(str); // STYLE_CHECK_ALLOW_STD_STRING_STREAM
330	    Poco::AutoPtr<Poco::Util::XMLConfiguration> config{new Poco::Util::XMLConfiguration()};
331	    config->load(stream);
332	
333	    version = config->getUInt("version");
334	    if ((version < INITIAL_BACKUP_VERSION) || (version > CURRENT_BACKUP_VERSION))
335	        throw Exception(ErrorCodes::BACKUP_VERSION_NOT_SUPPORTED, "Backup {}: Version {} is not supported", backup_name, version);
336	
337	    timestamp = parse<LocalDateTime>(config->getString("timestamp")).to_time_t();
338	    uuid = parse<UUID>(config->getString("uuid"));
339	
340	    if (config->has("base_backup") && !base_backup_info)
341	        base_backup_info = BackupInfo::fromString(config->getString("base_backup"));
342	
343	    if (config->has("base_backup_uuid"))
344	        base_backup_uuid = parse<UUID>(config->getString("base_backup_uuid"));
345	
346	    Poco::Util::AbstractConfiguration::Keys keys;
347	    config->keys("contents", keys);
348	    for (const auto & key : keys)
349	    {
350	        if ((key == "file") || key.starts_with("file["))
351	        {
352	            String prefix = "contents." + key + ".";
353	            FileInfo info;
354	            info.file_name = config->getString(prefix + "name");
355	            info.size = config->getUInt(prefix + "size");
356	            if (info.size)
357	            {
358	                info.checksum = unhexChecksum(config->getString(prefix + "checksum"));
359	
360	                bool use_base = config->getBool(prefix + "use_base", false);
361	                info.base_size = config->getUInt(prefix + "base_size", use_base ? info.size : 0);
362	                if (info.base_size)
363	                    use_base = true;
364	
365	                if (info.base_size > info.size)
366	                    throw Exception(ErrorCodes::BACKUP_DAMAGED, "Backup {}: Base size must not be greater than the size of entry {}", backup_name, quoteString(info.file_name));
367	
368	                if (use_base)
369	                {
370	                    if (info.base_size == info.size)
371	                        info.base_checksum = info.checksum;
372	                    else
373	                        info.base_checksum = unhexChecksum(config->getString(prefix + "base_checksum"));
374	                }
375	
376	                if (info.size > info.base_size)
377	                {
378	                    info.data_file_name = config->getString(prefix + "data_file", info.file_name);
379	                    info.archive_suffix = config->getString(prefix + "archive_suffix", "");
380	                    info.pos_in_archive = config->getUInt64(prefix + "pos_in_archive", static_cast<UInt64>(-1));
381	                }
382	            }
383	
384	            coordination->addFileInfo(info);
385	        }
386	    }
387	}
