389	void BackupImpl::checkBackupDoesntExist() const
390	{
391	    String file_name_to_check_existence;
392	    if (use_archives)
393	        file_name_to_check_existence = archive_params.archive_name;
394	    else
395	        file_name_to_check_existence = ".backup";
396	
397	    if (writer->fileExists(file_name_to_check_existence))
398	        throw Exception(ErrorCodes::BACKUP_ALREADY_EXISTS, "Backup {} already exists", backup_name);
399	
400	    /// Check that no other backup (excluding internal backups) is writing to the same destination.
401	    if (!is_internal_backup)
402	    {
403	        assert(!lock_file_name.empty());
404	        if (writer->fileExists(lock_file_name))
405	            throw Exception(ErrorCodes::BACKUP_ALREADY_EXISTS, "Backup {} is being written already", backup_name);
406	    }
