419	bool BackupImpl::checkLockFile(bool throw_if_failed) const
420	{
421	    if (!lock_file_name.empty() && uuid && writer->fileContentsEqual(lock_file_name, toString(*uuid)))
422	        return true;
423	
424	    if (throw_if_failed)
425	    {
426	        if (!writer->fileExists(lock_file_name))
427	            throw Exception(ErrorCodes::FAILED_TO_SYNC_BACKUP_OR_RESTORE, "Lock file {} suddenly disappeared while writing backup {}", lock_file_name, backup_name);
428	        throw Exception(ErrorCodes::BACKUP_ALREADY_EXISTS, "A concurrent backup writing to the same destination {} detected", backup_name);
