507	BackupEntryPtr BackupImpl::readFile(const SizeAndChecksum & size_and_checksum) const
508	{
509	    std::lock_guard lock{mutex};
510	    if (open_mode != OpenMode::READ)
511	        throw Exception("Backup is not opened for reading", ErrorCodes::LOGICAL_ERROR);
512	
513	    if (!size_and_checksum.first)
514	    {
515	        /// Entry's data is empty.
516	        return std::make_unique<BackupEntryFromMemory>(nullptr, 0, UInt128{0, 0});
517	    }
518	
519	    auto info_opt = coordination->getFileInfo(size_and_checksum);
520	    if (!info_opt)
521	        throw Exception(
522	            ErrorCodes::BACKUP_ENTRY_NOT_FOUND, "Backup {}: Entry {} not found in the backup", backup_name, formatSizeAndChecksum(size_and_checksum));
523	
524	    const auto & info = *info_opt;
525	
526	    if (!info.base_size)
527	    {
528	        /// Data goes completely from this backup, the base backup isn't used.
529	        return std::make_unique<BackupEntryFromBackupImpl>(
530	            std::static_pointer_cast<const BackupImpl>(shared_from_this()), info.archive_suffix, info.data_file_name, info.size, info.checksum);
531	    }
532	
533	    if (!base_backup)
534	    {
535	        throw Exception(
536	            ErrorCodes::NO_BASE_BACKUP,
537	            "Backup {}: Entry {} is marked to be read from a base backup, but there is no base backup specified",
538	            backup_name, formatSizeAndChecksum(size_and_checksum));
539	    }
540	
541	    if (!base_backup->fileExists(std::pair(info.base_size, info.base_checksum)))
542	    {
543	        throw Exception(
544	            ErrorCodes::WRONG_BASE_BACKUP,
545	            "Backup {}: Entry {} is marked to be read from a base backup, but doesn't exist there",
546	            backup_name, formatSizeAndChecksum(size_and_checksum));
547	    }
548	
549	    auto base_entry = base_backup->readFile(std::pair{info.base_size, info.base_checksum});
550	
551	    if (info.size == info.base_size)
552	    {
553	        /// Data goes completely from the base backup (nothing goes from this backup).
554	        return base_entry;
555	    }
556	
557	    {
558	        /// The beginning of the data goes from the base backup,
559	        /// and the ending goes from this backup.
560	        return std::make_unique<BackupEntryFromBackupImpl>(
561	            static_pointer_cast<const BackupImpl>(shared_from_this()), info.archive_suffix, info.data_file_name, info.size, info.checksum, std::move(base_entry));
562	    }
563	}
