566	void BackupImpl::writeFile(const String & file_name, BackupEntryPtr entry)
567	{
568	    std::lock_guard lock{mutex};
569	    if (open_mode != OpenMode::WRITE)
570	        throw Exception("Backup is not opened for writing", ErrorCodes::LOGICAL_ERROR);
571	
572	    if (writing_finalized)
573	        throw Exception("Backup is already finalized", ErrorCodes::LOGICAL_ERROR);
574	
575	    auto adjusted_path = removeLeadingSlash(file_name);
576	    if (coordination->getFileInfo(adjusted_path))
577	        throw Exception(
578	            ErrorCodes::BACKUP_ENTRY_ALREADY_EXISTS, "Backup {}: Entry {} already exists", backup_name, quoteString(file_name));
579	
580	    FileInfo info;
581	    info.file_name = adjusted_path;
582	    size_t size = entry->getSize();
583	    info.size = size;
584	
585	    /// Check if the entry's data is empty.
586	    if (!info.size)
587	    {
588	        coordination->addFileInfo(info);
589	        return;
590	    }
591	
592	    /// Maybe we have a copy of this file in the backup already.
593	    std::optional<UInt128> checksum = entry->getChecksum();
594	    if (checksum && coordination->getFileInfo(std::pair{size, *checksum}))
595	    {
596	        info.checksum = *checksum;
597	        coordination->addFileInfo(info);
598	        return;
599	    }
600	
601	    /// Check if a entry with such name exists in the base backup.
602	    bool base_exists = (base_backup && base_backup->fileExists(adjusted_path));
603	    UInt64 base_size = 0;
604	    UInt128 base_checksum{0, 0};
605	    if (base_exists)
606	    {
607	        base_size = base_backup->getFileSize(adjusted_path);
608	        base_checksum = base_backup->getFileChecksum(adjusted_path);
609	    }
610	
611	    std::unique_ptr<SeekableReadBuffer> read_buffer; /// We'll set that later.
612	    std::optional<HashingReadBuffer> hashing_read_buffer;
613	    UInt64 hashing_pos = 0; /// Current position in `hashing_read_buffer`.
614	
615	    /// Determine whether it's possible to receive this entry's data from the base backup completely or partly.
616	    bool use_base = false;
617	    if (base_exists && base_size && (size >= base_size))
618	    {
619	        if (checksum && (size == base_size))
620	        {
621	            /// The size is the same, we need to compare checksums to find out
622	            /// if the entry's data has not changed since the base backup.
623	            use_base = (*checksum == base_checksum);
624	        }
625	        else
626	        {
627	            /// The size has increased, we need to calculate a partial checksum to find out
628	            /// if the entry's data has only appended since the base backup.
629	            read_buffer = entry->getReadBuffer();
630	            hashing_read_buffer.emplace(*read_buffer);
631	            hashing_read_buffer->ignore(base_size);
632	            hashing_pos = base_size;
633	            UInt128 partial_checksum = hashing_read_buffer->getHash();
634	            if (size == base_size)
635	                checksum = partial_checksum;
636	            if (partial_checksum == base_checksum)
637	                use_base = true;
638	        }
639	    }
640	
641	    /// Finish calculating the checksum.
642	    if (!checksum)
643	    {
644	        if (!read_buffer)
645	            read_buffer = entry->getReadBuffer();
646	        if (!hashing_read_buffer)
647	            hashing_read_buffer.emplace(*read_buffer);
648	        hashing_read_buffer->ignore(size - hashing_pos);
649	        checksum = hashing_read_buffer->getHash();
650	    }
651	    hashing_read_buffer.reset();
652	    info.checksum = *checksum;
653	
654	    /// Maybe we have a copy of this file in the backup already.
655	    if (coordination->getFileInfo(std::pair{size, *checksum}))
656	    {
657	        coordination->addFileInfo(info);
658	        return;
659	    }
660	
661	    /// Check if a entry with the same checksum exists in the base backup.
662	    if (base_backup && !use_base && base_backup->fileExists(std::pair{size, *checksum}))
663	    {
664	        /// The entry's data has not changed since the base backup,
665	        /// but the entry itself has been moved or renamed.
666	        base_size = size;
667	        base_checksum = *checksum;
668	        use_base = true;
669	    }
670	
671	    if (use_base)
672	    {
673	        info.base_size = base_size;
674	        info.base_checksum = base_checksum;
675	    }
676	
677	    if (use_base && (size == base_size))
678	    {
679	        /// The entry's data has not been changed since the base backup.
680	        coordination->addFileInfo(info);
681	        return;
682	    }
683	
684	    bool is_data_file_required;
685	    info.data_file_name = info.file_name;
686	    info.archive_suffix = current_archive_suffix;
687	    coordination->addFileInfo(info, is_data_file_required);
688	    if (!is_data_file_required)
689	        return; /// We copy data only if it's a new combination of size & checksum.
690	
691	    /// Either the entry wasn't exist in the base backup
692	    /// or the entry has data appended to the end of the data from the base backup.
693	    /// In both those cases we have to copy data to this backup.
694	
695	    /// Find out where the start position to copy data is.
696	    auto copy_pos = use_base ? base_size : 0;
697	
698	    /// Move the current read position to the start position to copy data.
699	    if (!read_buffer)
700	        read_buffer = entry->getReadBuffer();
701	    read_buffer->seek(copy_pos, SEEK_SET);
702	
703	    if (!num_files_written)
704	        checkLockFile(true);
705	
706	    /// Copy the entry's data after `copy_pos`.
707	    std::unique_ptr<WriteBuffer> out;
708	    if (use_archives)
709	    {
710	        String archive_suffix = current_archive_suffix;
711	        bool next_suffix = false;
712	        if (current_archive_suffix.empty() && is_internal_backup)
713	            next_suffix = true;
714	        /*if (archive_params.max_volume_size && current_archive_writer
715	            && (current_archive_writer->getTotalSize() + size - base_size > archive_params.max_volume_size))
716	            next_suffix = true;*/
717	        if (next_suffix)
718	            current_archive_suffix = coordination->getNextArchiveSuffix();
719	        if (info.archive_suffix != current_archive_suffix)
720	        {
721	            info.archive_suffix = current_archive_suffix;
722	            coordination->updateFileInfo(info);
723	        }
724	        out = getArchiveWriter(current_archive_suffix)->writeFile(info.data_file_name);
725	    }
726	    else
727	    {
728	        out = writer->writeFile(info.data_file_name);
729	    }
730	
731	    copyData(*read_buffer, *out);
732	    out->finalize();
733	    ++num_files_written;
734	}
