737	void BackupImpl::finalizeWriting()
738	{
739	    std::lock_guard lock{mutex};
740	    if (open_mode != OpenMode::WRITE)
741	        throw Exception("Backup is not opened for writing", ErrorCodes::LOGICAL_ERROR);
742	
743	    if (writing_finalized)
744	        throw Exception("Backup is already finalized", ErrorCodes::LOGICAL_ERROR);
745	
746	    if (!coordination->hasFiles(""))
747	        throw Exception("Backup must not be empty", ErrorCodes::BACKUP_IS_EMPTY);
748	
749	    if (!is_internal_backup)
750	    {
751	        LOG_TRACE(log, "Finalizing backup {}", backup_name);
752	        writeBackupMetadata();
753	        removeLockFile();
754	        LOG_TRACE(log, "Finalized backup {}", backup_name);
755	    }
756	
757	    writing_finalized = true;
758	}
