767	std::shared_ptr<IArchiveReader> BackupImpl::getArchiveReader(const String & suffix) const
768	{
769	    auto it = archive_readers.find(suffix);
770	    if (it != archive_readers.end())
771	        return it->second;
772	    String archive_name_with_suffix = getArchiveNameWithSuffix(suffix);
773	    size_t archive_size = reader->getFileSize(archive_name_with_suffix);
774	    auto new_archive_reader = createArchiveReader(archive_params.archive_name, [reader=reader, archive_name_with_suffix]{ return reader->readFile(archive_name_with_suffix); },
775	        archive_size);
776	    new_archive_reader->setPassword(archive_params.password);
777	    archive_readers.emplace(suffix, new_archive_reader);
778	    return new_archive_reader;
