781	std::shared_ptr<IArchiveWriter> BackupImpl::getArchiveWriter(const String & suffix)
782	{
783	    for (const auto & archive_writer : archive_writers)
784	    {
785	        if ((suffix == archive_writer.first) && archive_writer.second)
786	            return archive_writer.second;
787	    }
788	
789	    String archive_name_with_suffix = getArchiveNameWithSuffix(suffix);
790	    auto new_archive_writer = createArchiveWriter(archive_params.archive_name, writer->writeFile(archive_name_with_suffix));
791	    new_archive_writer->setPassword(archive_params.password);
792	
793	    size_t pos = suffix.empty() ? 0 : 1;
794	    archive_writers[pos] = {suffix, new_archive_writer};
795	
796	    return new_archive_writer;
797	}
