799	void BackupImpl::removeAllFilesAfterFailure()
800	{
801	    if (is_internal_backup)
802	        return; /// Let the initiator remove unnecessary files.
803	
804	    try
805	    {
806	        LOG_INFO(log, "Removing all files of backup {} after failure", backup_name);
807	
808	        Strings files_to_remove;
809	        if (use_archives)
810	        {
811	            files_to_remove.push_back(archive_params.archive_name);
812	            for (const auto & suffix : coordination->getAllArchiveSuffixes())
813	            {
814	                String archive_name_with_suffix = getArchiveNameWithSuffix(suffix);
815	                files_to_remove.push_back(std::move(archive_name_with_suffix));
816	            }
817	        }
818	        else
819	        {
820	            files_to_remove.push_back(".backup");
821	            for (const auto & file_info : coordination->getAllFileInfos())
822	                files_to_remove.push_back(file_info.data_file_name);
823	        }
824	
825	        if (!checkLockFile(false))
826	            return;
827	
828	        writer->removeFiles(files_to_remove);
829	        removeLockFile();
830	    }
831	    catch (...)
832	    {
833	        DB::tryLogCurrentException(__PRETTY_FUNCTION__);
834	    }
835	}
